@typeparam TItem

<div class="infinite-scroll-container">
    @foreach (var item in Items)
    {
        @ChildContent(item)
    }

    @if (HasMore)
    {
        <div class="infinite-scroll-sentinel" @ref="sentinelRef">
            <div class="infinite-scroll-spinner"></div>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public IReadOnlyList<TItem> Items { get; set; } = [];

    [Parameter, EditorRequired]
    public bool HasMore { get; set; }

    [Parameter, EditorRequired]
    public EventCallback OnLoadMore { get; set; }

    [Parameter, EditorRequired]
    public RenderFragment<TItem> ChildContent { get; set; } = default!;

    private ElementReference sentinelRef;
    private IJSObjectReference? observerModule;
    private DotNetObjectReference<InfiniteScrollList<TItem>>? dotNetRef;
    private bool isLoading;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            dotNetRef = DotNetObjectReference.Create(this);
            observerModule = await JS.InvokeAsync<IJSObjectReference>(
                "import", "./_content/sv-e7414f2a5f154b79a6619e30e21020c5/InfiniteScrollList.razor.js");
        }

        if (HasMore && observerModule is not null)
        {
            await observerModule.InvokeVoidAsync("observe", sentinelRef, dotNetRef);
        }
    }

    [JSInvokable]
    public async Task OnSentinelVisible()
    {
        if (isLoading || !HasMore) return;

        isLoading = true;
        await OnLoadMore.InvokeAsync();
        isLoading = false;
    }

    [Inject]
    private IJSRuntime JS { get; set; } = default!;

    public async ValueTask DisposeAsync()
    {
        if (observerModule is not null)
        {
            await observerModule.InvokeVoidAsync("disconnect");
            await observerModule.DisposeAsync();
        }
        dotNetRef?.Dispose();
    }
}

let observer = null;

export function observe(sentinel, dotNetRef) {
    disconnect();

    observer = new IntersectionObserver(entries => {
        for (const entry of entries) {
            if (entry.isIntersecting) {
                dotNetRef.invokeMethodAsync('OnSentinelVisible');
            }
        }
    }, { rootMargin: '200px' });

    observer.observe(sentinel);
}

export function disconnect() {
    if (observer) {
        observer.disconnect();
        observer = null;
    }
}

.infinite-scroll-container {
    overflow-y: auto;
}

.infinite-scroll-sentinel {
    display: flex;
    justify-content: center;
    padding: 1rem;
}

.infinite-scroll-spinner {
    width: 2rem;
    height: 2rem;
    border: 3px solid #e0e0e0;
    border-top-color: #666;
    border-radius: 50%;
    animation: spin 0.8s linear infinite;
}

@@keyframes spin {
    to {
        transform: rotate(360deg);
    }
}

